-- 0115: 9 938 literal products; preserve all installed products and secured purchases.
-- New authenticated catalog-page RPC + indexes. shop_state product aggregation only
-- is narrowed to legacy/wished/promoted items; all other state and writes unchanged.
BEGIN;
LOCK TABLE public.economy_catalog IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.economy_catalog WHERE id LIKE 'shop-v1-0115-%') THEN RAISE EXCEPTION '0115 déjà installée : ne pas relancer'; END IF;
 IF (SELECT count(*) FROM public.economy_catalog WHERE config->>'shop'='true') <> 62 THEN RAISE EXCEPTION 'Catalogue différent de 62 : arrêt sans modification'; END IF;
 IF to_regprocedure('public.shop_state()') IS NULL OR to_regprocedure('public.shop_promos(timestamp with time zone)') IS NULL THEN RAISE EXCEPTION 'Prérequis boutique manquants'; END IF;
END $$;
CREATE TEMP TABLE original_catalog_0115 ON COMMIT DROP AS SELECT id,to_jsonb(e) AS row FROM public.economy_catalog e;
-- BEGIN LITERAL PRODUCTS
-- END LITERAL PRODUCTS

CREATE INDEX catalog_shop_section_0115 ON public.economy_catalog((config->>'section'),sort_order,id) WHERE config->>'shop'='true';
CREATE INDEX shop_orders_catalog_0115 ON public.shop_orders(catalog_id);
-- Match precisely the installed 0078 aggregation before changing its WHERE only.
DO $$ DECLARE body text; needle text := 'FROM public.economy_catalog ec WHERE COALESCE(ec.config->>''shop'', ''false'') = ''true''), ''[]'')'; BEGIN
 SELECT pg_get_functiondef('public.shop_state()'::regprocedure) INTO body;
 IF (length(body)-length(replace(body,needle,'')))/length(needle) <> 1 THEN RAISE EXCEPTION 'shop_state inattendue : arrêt atomique'; END IF;
 body := replace(body,needle,
 'FROM public.economy_catalog ec WHERE COALESCE(ec.config->>''shop'', ''false'') = ''true'' AND (ec.config->>''catalog_pack'' IS DISTINCT FROM ''v1-0115'' OR EXISTS(SELECT 1 FROM public.shop_wishlist w WHERE w.character_id=cid AND w.catalog_id=ec.id) OR ec.id IN (SELECT catalog_id FROM public.shop_promos(t)))), ''[]'')');
 EXECUTE body;
END $$;

CREATE FUNCTION public.shop_catalog_page(_search text DEFAULT '', _section text DEFAULT '', _brand text DEFAULT '', _max integer DEFAULT NULL, _sort text DEFAULT 'populaire', _city text DEFAULT '', _rooms integer DEFAULT NULL, _offset integer DEFAULT 0, _limit integer DEFAULT 24) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE cid uuid := public.social_actor(); result jsonb; t timestamptz := public.game_now();
BEGIN
 IF cid IS NULL THEN RAISE EXCEPTION 'Personnage connecté requis'; END IF;
 IF _offset IS NULL OR _offset < 0 OR _offset > 100000 OR _limit IS NULL OR _limit NOT BETWEEN 1 AND 48 THEN RAISE EXCEPTION 'Page invalide'; END IF;
 IF _sort IS NULL OR _sort NOT IN ('populaire','nom','prix-asc','prix-desc') OR char_length(coalesce(_search,''))>200 THEN RAISE EXCEPTION 'Filtre invalide'; END IF;
 WITH promos AS MATERIALIZED (SELECT * FROM public.shop_promos(t)),
 sales AS (SELECT catalog_id,count(*) AS n FROM public.shop_orders GROUP BY catalog_id),
 catalog AS MATERIALIZED (
  SELECT ec.*,coalesce(s.n,0) AS sales,coalesce(p.percent,0) AS pct,
   ec.price-floor(ec.price*coalesce(p.percent,0)/100.0)::integer AS cash_price
  FROM public.economy_catalog ec LEFT JOIN sales s ON s.catalog_id=ec.id LEFT JOIN promos p ON p.catalog_id=ec.id WHERE ec.config->>'shop'='true'
 ), filtered AS MATERIALIZED (
  SELECT * FROM catalog WHERE
   (coalesce(_search,'')='' OR strpos(lower(coalesce(config->>'brand','') || ' ' || name),lower(btrim(_search)))>0)
   AND (coalesce(_section,'')='' OR config->>'section'=_section)
   AND (coalesce(_brand,'')='' OR config->>'brand'=_brand)
   AND (_max IS NULL OR cash_price<=_max)
   AND (coalesce(_city,'')='' OR config->>'city'=_city)
   AND (_rooms IS NULL OR config->>'rooms'=_rooms::text)
 ), numbered AS (
  SELECT *,row_number() OVER(ORDER BY
   CASE WHEN _sort='populaire' THEN sales END DESC,
   CASE WHEN _sort IN ('populaire','prix-asc') THEN cash_price END ASC,
   CASE WHEN _sort='prix-desc' THEN cash_price END DESC,
   CASE WHEN _sort='nom' THEN name END ASC, id ASC) AS rn FROM filtered
 ), page AS (SELECT * FROM numbered WHERE rn>_offset AND rn<=_offset+_limit)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM filtered),'catalog_total',(SELECT count(*) FROM catalog),
  'brands',(SELECT coalesce(jsonb_agg(b ORDER BY b),'[]'::jsonb) FROM (SELECT DISTINCT config->>'brand' b FROM catalog WHERE config->>'brand' IS NOT NULL) b),
  'products',coalesce((SELECT jsonb_agg(jsonb_build_object(
   'id',ec.id,'name',ec.name,'price',ec.price,'kind',ec.kind,'brand',ec.config->>'brand','section',ec.config->>'section',
   'desc',ec.config->>'desc','dep',(ec.config->>'dep')::integer,'details',ec.config-'shop'-'desc'-'brand'-'section'-'dep',
   'owned',EXISTS(SELECT 1 FROM public.personal_assets a WHERE a.character_id=cid AND a.catalog_id=ec.id), 'sales',ec.sales) ORDER BY rn) FROM page ec),'[]'::jsonb)) INTO result;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.shop_catalog_page(text,text,text,integer,text,text,integer,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.shop_catalog_page(text,text,text,integer,text,text,integer,integer,integer) TO authenticated;
DO $$ BEGIN
 IF (SELECT count(*) FROM public.economy_catalog WHERE config->>'shop'='true') <> 10000 THEN RAISE EXCEPTION '10 000 produits requis'; END IF;
 IF (SELECT count(*) FROM public.economy_catalog WHERE config->>'catalog_pack'='v1-0115') <> 9938 THEN RAISE EXCEPTION '9 938 ajouts requis'; END IF;
 IF EXISTS(SELECT 1 FROM original_catalog_0115 old LEFT JOIN public.economy_catalog e USING(id) WHERE old.row IS DISTINCT FROM to_jsonb(e)) THEN RAISE EXCEPTION 'Ancien produit modifié'; END IF;
 IF EXISTS(SELECT 1 FROM public.economy_catalog WHERE config->>'catalog_pack'='v1-0115' AND NOT (
  (config->>'price_group'='accessoires' AND price BETWEEN 5 AND 100) OR
  (config->>'price_group' IN ('mode','sport') AND price BETWEEN 10 AND 500) OR
  (config->>'price_group'='mobilier' AND price BETWEEN 25 AND 3000) OR
  (config->>'price_group' IN ('tech','electromenager') AND price BETWEEN 20 AND 3000))) THEN RAISE EXCEPTION 'Prix hors fourchettes validées'; END IF;
END $$;
SELECT count(*) AS produits_catalogue FROM public.economy_catalog WHERE config->>'shop'='true';
COMMIT;